CREATE TABLE IF NOT EXISTS statuses (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::TEXT, entity_type TEXT NOT NULL, name TEXT NOT NULL, label TEXT NOT NULL, color TEXT NOT NULL DEFAULT '#f0f0f0', text_color TEXT NOT NULL DEFAULT '#666', sort_order INTEGER NOT NULL DEFAULT 0, is_default BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT statuses_entity_type_name_unique UNIQUE (entity_type, name)); CREATE INDEX IF NOT EXISTS statuses_entity_type_sort_order_idx ON statuses(entity_type, sort_order); INSERT INTO statuses (id, entity_type, name, label, color, text_color, sort_order, is_default) VALUES (gen_random_uuid()::TEXT, 'task', 'open', 'Открыта', '#f0f0f0', '#666', 0, true), (gen_random_uuid()::TEXT, 'task', 'in_progress', 'В работе', '#fef3c7', '#92400e', 1, false), (gen_random_uuid()::TEXT, 'task', 'done', 'Выполнена', '#dcfce7', '#166534', 2, false), (gen_random_uuid()::TEXT, 'task', 'cancelled', 'Отменена', '#fee2e2', '#991b1b', 3, false), (gen_random_uuid()::TEXT, 'project', 'active', 'Активен', '#dcfce7', '#166534', 0, true), (gen_random_uuid()::TEXT, 'project', 'paused', 'На паузе', '#fef3c7', '#92400e', 1, false), (gen_random_uuid()::TEXT, 'project', 'completed', 'Завершён', '#dbeafe', '#1e40af', 2, false), (gen_random_uuid()::TEXT, 'project', 'archived', 'В архиве', '#f3f4f6', '#6b7280', 3, false), (gen_random_uuid()::TEXT, 'deal', 'lead', 'Первичный контакт', '#f0f0f0', '#666', 0, true), (gen_random_uuid()::TEXT, 'deal', 'contact', 'Контакт', '#dbeafe', '#1e40af', 1, false), (gen_random_uuid()::TEXT, 'deal', 'proposal', 'КП', '#fef3c7', '#92400e', 2, false), (gen_random_uuid()::TEXT, 'deal', 'negotiation', 'Переговоры', '#fef9c3', '#854d0e', 3, false), (gen_random_uuid()::TEXT, 'deal', 'contract', 'Договор', '#dcfce7', '#166534', 4, false), (gen_random_uuid()::TEXT, 'deal', 'won', 'Выиграно', '#dcfce7', '#166534', 5, false), (gen_random_uuid()::TEXT, 'deal', 'lost', 'Проиграно', '#fee2e2', '#991b1b', 6, false) ON CONFLICT DO NOTHING;